def calculate_value(x1, x2):
    deviation = 0
    if x1 > 0 and x2 > 0:
        deviation = 1
    elif x1 < 0 and x2 > 0:
        deviation = -1
    elif x1 > 0 and x2 <= 0:
        deviation = 0
    elif x1 < 0 and x2 <= 0:
        deviation = -2
    result = x1**2 - abs(x2) + deviation
    return result

def calculate_value(x1, x2, x3, x4):
    deviation = 0
    if x1 > 0 and x2 > 0 and x3 > 0:
        deviation = 2
    elif x1 < 0 and x2 < 0 and x3 < 0:
        deviation = -1
    elif abs(x1) > 2 and abs(x2) > 2 and abs(x3) > 2:
        deviation = 0
    return x1 * x2 * x3 - x4 + deviation
